<script setup lang="ts">
import { cn } from '@comfyorg/tailwind-utils'
import { autoUpdate, offset, shift, useFloating } from '@floating-ui/vue'
import type { Middleware } from '@floating-ui/vue'
import {
  useElementBounding,
  useEventListener,
  useWindowSize
} from '@vueuse/core'
import { FocusScope } from 'reka-ui'
import { computed, nextTick, onBeforeUnmount, ref, useId, watch } from 'vue'

import { vRekaZIndex } from '@agent/components/dialog/vRekaZIndex'
import Button from '@agent/components/ui/button/Button.vue'
import { clampSpotlight } from '@agent/platform/onboarding/coachmarkLayout'
import type { CoachStep } from '../../composables/agent/useOnboarding'
import { useOnboarding } from '../../composables/agent/useOnboarding'

const { steps, storageKey } = defineProps<{
  steps: CoachStep[]
  storageKey?: string
}>()

const { active, index, step, isLast, next, finish } = useOnboarding(
  () => steps,
  storageKey
)
const titleId = useId()
const bodyId = useId()
const target = ref<HTMLElement | null>(null)
const toolbar = ref<HTMLElement | null>(null)
const card = ref<HTMLElement | null>(null)
const bounds = useElementBounding(target)
const toolbarBounds = useElementBounding(toolbar)
const { width, height } = useWindowSize()
let targetRetryTimer: ReturnType<typeof setTimeout> | undefined

function scheduleTargetRetry(): void {
  clearTimeout(targetRetryTimer)
  if (!active.value || target.value) return
  targetRetryTimer = setTimeout(() => {
    resolveTargets()
    scheduleTargetRetry()
  }, 50)
}

function resolveTargets(): void {
  const nextTarget = active.value
    ? document.querySelector<HTMLElement>(step.value.target)
    : null
  const nextToolbar =
    active.value && step.value.toolbarTarget
      ? document.querySelector<HTMLElement>(step.value.toolbarTarget)
      : null
  if (target.value !== nextTarget) target.value = nextTarget
  if (toolbar.value !== nextToolbar) toolbar.value = nextToolbar
  bounds.update()
  toolbarBounds.update()
  scheduleTargetRetry()
}

const targetObserver = new MutationObserver(resolveTargets)
targetObserver.observe(document.body, {
  childList: true,
  subtree: true
})
onBeforeUnmount(() => {
  targetObserver.disconnect()
  clearTimeout(targetRetryTimer)
})

watch(
  [active, step],
  async () => {
    await nextTick()
    resolveTargets()
  },
  { immediate: true, flush: 'post' }
)

const middleware = computed<Middleware[]>(() => {
  const result = [
    offset({
      mainAxis: 16,
      crossAxis: step.value?.placement === 'left-start' ? -16 : 0
    })
  ]
  if (step.value?.placement === 'graph-bottom') {
    const bottom = toolbar.value ? toolbarBounds.top.value : bounds.bottom.value
    result.push({
      name: 'graphBottom',
      fn: ({ rects }) => ({
        x:
          rects.reference.x +
          (rects.reference.width - rects.floating.width) / 2,
        y:
          Math.min(bottom, rects.reference.y + rects.reference.height) -
          16 -
          rects.floating.height
      })
    })
  }
  return [...result, shift({ padding: 8, crossAxis: true })]
})

const { floatingStyles, isPositioned } = useFloating(target, card, {
  strategy: 'fixed',
  transform: false,
  placement: () =>
    step.value?.placement === 'left-center'
      ? 'left'
      : step.value?.placement === 'left-end'
        ? 'left-end'
        : 'left-start',
  middleware,
  whileElementsMounted: autoUpdate
})

const spotlightStyle = computed(() =>
  clampSpotlight(
    new DOMRect(
      bounds.left.value,
      bounds.top.value,
      bounds.width.value,
      bounds.height.value
    ),
    0,
    { width: width.value, height: height.value }
  )
)

useEventListener(
  document,
  'keydown',
  (event) => {
    if (!active.value || !target.value || event.key !== 'Escape') return
    event.preventDefault()
    event.stopPropagation()
    finish()
  },
  { capture: true }
)
</script>

<template>
  <Teleport to="body">
    <div
      v-if="active && target"
      v-reka-z-index
      class="agent-scope ctv:fixed ctv:inset-0"
    >
      <div class="ctv:absolute ctv:inset-0" />
      <div
        aria-hidden="true"
        data-testid="agent-coach-spotlight"
        :style="{ ...spotlightStyle }"
        class="ctv:pointer-events-none ctv:absolute ctv:rounded-lg ctv:shadow-[0_0_0_9999px_var(--color-coach-scrim)]"
      />
      <FocusScope as-child trapped loop>
        <div
          ref="card"
          role="dialog"
          aria-modal="true"
          :aria-labelledby="titleId"
          :aria-describedby="bodyId"
          tabindex="-1"
          :style="{
            ...floatingStyles,
            opacity: isPositioned ? 1 : 0
          }"
          :class="
            cn(
              'ctv:fixed ctv:box-border ctv:flex ctv:max-h-[calc(100vh-16px)] ctv:w-[307px] ctv:max-w-[calc(100vw-16px)] ctv:flex-col ctv:gap-3 ctv:overflow-y-auto ctv:rounded-2xl ctv:border ctv:bg-base-background ctv:p-4 ctv:font-inter ctv:text-base-foreground ctv:shadow-lg',
              index < 2
                ? 'ctv:border-secondary-background'
                : 'ctv:border-alpha-smoke-500-20'
            )
          "
        >
          <div class="ctv:flex ctv:flex-col ctv:gap-6">
            <div class="ctv:flex ctv:flex-col ctv:gap-2">
              <p class="ctv:m-0 ctv:text-xs/normal ctv:opacity-50">
                {{
                  $t('agent.coachProgress', {
                    current: index + 1,
                    total: steps.length
                  })
                }}
              </p>
              <h3 :id="titleId" class="ctv:m-0 ctv:text-base/normal ctv:font-semibold">
                {{ step.title }}
              </h3>
              <p :id="bodyId" class="ctv:m-0 ctv:text-sm/normal ctv:text-muted-foreground">
                {{ step.body }}
              </p>
            </div>
            <div class="ctv:flex ctv:justify-end ctv:gap-3">
              <Button variant="secondary" size="md" @click="finish">{{
                $t('agent.skip')
              }}</Button>
              <Button variant="inverted" size="md" @click="next">{{
                $t(isLast ? 'onboardingCoachmarks.done' : 'g.next')
              }}</Button>
            </div>
          </div>
        </div>
      </FocusScope>
    </div>
  </Teleport>
</template>
